import styled from 'styled-components';
import { useState } from 'react';

export const Blocks = styled.div`
  display: flex;
  justify-content: space-evenly;
  padding: 100px;
  border: 1px solid black;
`;

export const Button = styled.button`
  width: clamp(100px, 11vw, 200px);
`;

export const Btn = styled.button`
  width: clamp(50px, 6vw, 100px);
`;

export const Btnmain = () => {
  const [disabledButtons, setDisabledButtons] = useState({
    button1: false,
    button2: false,
    button3: false,
  });

  const btnClick = () => {
    setDisabledButtons({
      button1: true,
      button2: true,
      button3: true,
    });
  };

  return (
    <Blocks className="buttons">
      <Button disabled={disabledButtons.button1}>Primery</Button>
      <Button disabled={disabledButtons.button2}>Secondary</Button>
      <Button disabled={disabledButtons.button3}>Secondary2</Button>
      <Btn onClick={btnClick}>заглушка</Btn>
    </Blocks>
  );
};
